mapper.sql:
d.tenant_id = #{tenantId}

  AND d.work_date >= CAST(#{query.startDate} AS DATE)


  AND d.work_date <= CAST(#{query.endDate} AS DATE)


  AND e.workplace_id = #{query.workplaceId}


  AND e.department_id = #{query.departmentId}


  AND (
    e.employee_no LIKE CONCAT('%', #{query.employeeKeyword}, '%')
    OR e.employee_name LIKE CONCAT('%', #{query.employeeKeyword}, '%')
  )


  AND d.status = #{query.status}


  AND d.exception_flag = 1

mapper.select:
SELECT DISTINCT target.employeeId AS employeeId, target.workDate AS workDate FROM ( SELECT s.employee_id AS employeeId, s.work_date AS workDate FROM shift_schedule s INNER JOIN employee e ON e.id = s.employee_id AND e.tenant_id = s.tenant_id WHERE s.tenant_id = #{tenantId}
AND s.work_date >= CAST(#{query.startDate} AS DATE)
AND s.work_date <= CAST(#{query.endDate} AS DATE)
AND e.workplace_id = #{query.workplaceId}
AND e.department_id = #{query.departmentId}
AND ( e.employee_no LIKE CONCAT('%', #{query.employeeKeyword}, '%') OR e.employee_name LIKE CONCAT('%', #{query.employeeKeyword}, '%') )
UNION SELECT p.employee_id AS employeeId, CAST(p.punch_time AS DATE) AS workDate FROM punch_raw_log p INNER JOIN employee e ON e.id = p.employee_id AND e.tenant_id = p.tenant_id WHERE p.tenant_id = #{tenantId} AND p.process_status = 'PROCESSED' AND p.employee_id IS NOT NULL
AND CAST(p.punch_time AS DATE) >= CAST(#{query.startDate} AS DATE)
AND CAST(p.punch_time AS DATE) <= CAST(#{query.endDate} AS DATE)
AND e.workplace_id = #{query.workplaceId}
AND e.department_id = #{query.departmentId}
AND ( e.employee_no LIKE CONCAT('%', #{query.employeeKeyword}, '%') OR e.employee_name LIKE CONCAT('%', #{query.employeeKeyword}, '%') )
) target ORDER BY target.workDate, target.employeeId

SELECT id, punch_time, punch_type, source_system, device_name
FROM punch_raw_log
WHERE tenant_id = #{tenantId}
  AND employee_id = #{employeeId}
  AND process_status = 'PROCESSED'
  AND CAST(punch_time AS DATE) = #{workDate}
ORDER BY punch_time ASC, id ASC

SELECT id, employee_id, work_date
FROM attendance_daily
WHERE tenant_id = #{tenantId}
  AND employee_id = #{employeeId}
  AND work_date = #{workDate}

mapper.delete:
DELETE FROM attendance_exception
WHERE tenant_id = #{tenantId}
  AND attendance_daily_id = #{attendanceDailyId}

DELETE FROM attendance_calc_log
WHERE tenant_id = #{tenantId}
  AND employee_id = #{employeeId}
  AND work_date = #{workDate}

mapper.select:
SELECT exception_type, exception_level, message, suggested_action
FROM attendance_exception
WHERE tenant_id = #{tenantId}
  AND attendance_daily_id = #{attendanceDailyId}
ORDER BY id ASC

SELECT step_name, step_message
FROM attendance_calc_log
WHERE tenant_id = #{tenantId}
  AND employee_id = #{employeeId}
  AND work_date = #{workDate}
ORDER BY id ASC
